    new_method = '''
    /**\n     * Ensures a recipient exists on the customer's gateway.\n     * If the recipient already exists in gateway_recipients (matched by user_id,\n     * gateway_id, channel_code, and account_identifier), the existing recipient code\n     * is returned. Otherwise, the recipient is created on the gateway and the mapping\n     * is persisted to gateway_recipients.\n     */\n    private String ensureRecipientOnSameGateway(UserModel user, GatewayCustomerModel gatewayCustomer,\n                                                PaymentRequest paymentRequest, GatewayModel gateway) {\n        String recipientName = paymentRequest.getRecipientName();\n        String recipientEmail = paymentRequest.getRecipientEmail();\n        String recipientPhone = paymentRequest.getRecipientPhoneNumber();\n        String amount = paymentRequest.getAmount().toString();\n        String currency = paymentRequest.getCurrency();\n\n        // Determine channel type based on payout option\n        String checkoutType = \"BANK\"; // default to bank transfer\n        String channelCode = paymentRequest.getRecipientBankCode();\n        if (paymentRequest.getPayoutOption() != null &&\n                paymentRequest.getPayoutOption().contains(\"Mobile Money\")) {\n            checkoutType = \"MOBILE_MONEY\";\n            channelCode = paymentRequest.getRecipientPhoneNumber();\n        }\n\n        // Check if recipient already exists for this user + gateway combination\n        GatewayRecipientsModel existing = gatewayRecipientRepository.findByUserIdAndGatewayIdAndChannelCode(\n                user.getUserId(), gateway.getProviderId(), channelCode);\n\n        if (existing != null) {\n            // Recipient already exists on this gateway - return the gateway recipient code\n            return existing.getGatewayRecipientId();\n        }\n\n        // Recipient does not exist - create on the gateway\n        String gatewayRecipientCode;\n        try {\n            if (\"PAYSTACK\".equals(gateway.getProviderName())) {\n                // Create recipient on Paystack\n                long amountInKobo = new java.math.BigDecimal(amount).multiply(new java.math.BigDecimal(\"100\")).longValueExact();\n                // Register recipient (bank account) with Paystack\n                gatewayRecipientCode = paystackServices.registerBankRecipient(\n                        gatewayCustomer.getGatewayCustomerId(), recipientName, channelCode, amountInKobo, currency);\n            } else if (\"FLUTTERWAVE\".equals(gateway.getProviderName())) {\n                // Create recipient on Flutterwave - Flutterwave transfers take destination details inline\n                long amountInUnits = new java.math.BigDecimal(amount).multiply(new java.math.BigDecimal(\"100\")).longValueExact();\n                FlutterwaveTransferResponseDTO transferResp = flutterwaveServices.initiateTransfer(\n                        \"BANK\",\n                        channelCode, // providerCode = bank code\n                        recipientPhone, // accountIdentifier\n                        recipientName,\n                        new java.math.BigDecimal(amount),\n                        currency,\n                        \"Zentrapay transfer - \" + System.currentTimeMillis(),\n                        \"ref-\" + System.currentTimeMillis()\n                );\n                gatewayRecipientCode = transferResp != null && transferResp.status()\n                    ? transferResp.transferId() : null;\n            } else {\n                // Onafriq - use inline details, no pre-registration needed\n                gatewayRecipientCode = \"ONAFRIQ-\" + System.currentTimeMillis();\n            }\n        } catch (Exception e) {\n            log.error(\"Failed to create recipient on gateway {}: {}\", gateway.getProviderName(), e.getMessage());\n            throw new RuntimeException(\"Recipient creation failed on gateway: \" + gateway.getProviderName(), e);\n        }\n\n        // Persist the recipient mapping to gateway_recipients table\n        GatewayRecipientsModel recipientMapping = new GatewayRecipientsModel();\n        recipientMapping.setUserId(user.getUserId());\n        recipientMapping.setGatewayId(gateway.getProviderId());\n        recipientMapping.setGateway(gateway.getProviderName());\n        recipientMapping.setGatewayRecipientId(gatewayRecipientCode);\n        recipientMapping.setChannelCode(channelCode);\n        recipientMapping.setCheckoutType(checkoutType);\n        recipientMapping.setAccountIdentifier(recipientPhone);\n        recipientMapping.setAccountName(recipientName);\n        gatewayRecipientRepository.save(recipientMapping);\n\n        return gatewayRecipientCode;\n    }\n'''
    
    # Replace the last "}\n}" with the new method + "}\n}"
